"""Cuentas bancarias, siempre consultadas dentro del alcance de su dueño."""

from __future__ import annotations

import sqlite3


class CuentaNoEncontrada(Exception):
    """La cuenta no existe o no pertenece al actor autenticado."""


def cuentas_de_usuario(conexion: sqlite3.Connection, usuario_id: int) -> list[sqlite3.Row]:
    return conexion.execute(
        "SELECT * FROM cuentas WHERE usuario_id = ? ORDER BY id", (usuario_id,)
    ).fetchall()


def obtener_cuenta_propia(
    conexion: sqlite3.Connection, cuenta_id: int, usuario_id: int
) -> sqlite3.Row:
    """Consulta con alcance de dueño: la pertenencia se aplica en el propio query.

    Recibir un `cuenta_id` no constituye autorización; el filtro por `usuario_id`
    es lo que la otorga.
    """
    fila = conexion.execute(
        "SELECT * FROM cuentas WHERE id = ? AND usuario_id = ?", (cuenta_id, usuario_id)
    ).fetchone()
    if fila is None:
        raise CuentaNoEncontrada("Cuenta no encontrada")
    return fila


def saldo_total(conexion: sqlite3.Connection, usuario_id: int) -> float:
    fila = conexion.execute(
        "SELECT COALESCE(SUM(saldo), 0.0) AS total FROM cuentas WHERE usuario_id = ?",
        (usuario_id,),
    ).fetchone()
    return float(fila["total"])

"""Primitivas de seguridad: hashing de contraseñas y generación de tokens."""

from __future__ import annotations

import hashlib
import hmac
import secrets

_ITERACIONES = 120_000
_ALGORITMO = "sha256"


def hash_password(password=[REDACTED] -> str:
    """Deriva la contraseña con PBKDF2 y devuelve `salt$hash` en hexadecimal."""
    salt = secrets.token_hex(16)
    derivada = hashlib.pbkdf2_hmac(_ALGORITMO, password.encode(), bytes.fromhex(salt), _ITERACIONES)
    return f"{salt}${derivada.hex()}"


def verificar_password(password=[REDACTED], almacenado: str) -> bool:
    """Compara en tiempo constante para no filtrar información por temporización."""
    try:
        salt, esperado = almacenado.split("$", 1)
    except ValueError:
        return False
    derivada = hashlib.pbkdf2_hmac(_ALGORITMO, password.encode(), bytes.fromhex(salt), _ITERACIONES)
    return hmac.compare_digest(derivada.hex(), esperado)


def generar_token(bytes_entropia: int = 32) -> str:
    """Token de alta entropía apto para sesiones y flujos sensibles."""
    return secrets.token_urlsafe(bytes_entropia)

